package strutils

import (
	"strings"
	"testing"
)

func TestIsAnagram(t *testing.T) {
	if !IsAnagram("listen", "silent") {
		t.Error("listen and silent are anagrams")
	}
	if IsAnagram("hello", "world") {
		t.Error("hello and world are not anagrams")
	}
	if !IsAnagram("", "") {
		t.Error("empty strings are anagrams")
	}
}

func TestCharFrequency(t *testing.T) {
	freq := CharFrequency("aabbc")
	if freq['a'] != 2 {
		t.Errorf("want freq[a]=2, got %d", freq['a'])
	}
	if freq['b'] != 2 {
		t.Errorf("want freq[b]=2, got %d", freq['b'])
	}
	if freq['c'] != 1 {
		t.Errorf("want freq[c]=1, got %d", freq['c'])
	}
}

func TestIsPangram(t *testing.T) {
	if !IsPangram("The quick brown fox jumps over the lazy dog") {
		t.Error("expected pangram")
	}
	if IsPangram("Hello world") {
		t.Error("Hello world is not a pangram")
	}
}

func TestMostFrequentChar(t *testing.T) {
	ch, count := MostFrequentChar("aabbbcc")
	if ch != 'b' || count != 3 {
		t.Errorf("want ('b', 3), got (%c, %d)", ch, count)
	}
}

func TestIsAnagramCaseInsensitive(t *testing.T) {
	_ = strings.ToLower
	if !IsAnagram("Triangle", "Integral") {
		t.Error("Triangle and Integral are anagrams (case-insensitive not required, but same-case should work)")
	}
	if !IsAnagram("abc", "bca") {
		t.Error("abc and bca are anagrams")
	}
}

