Implement four string-analysis functions in strutils.go.

func IsAnagram(s1, s2 string) bool
  // True if s1 and s2 contain the same characters with the same frequencies.
  // Case-sensitive. Empty strings are anagrams of each other.

func CharFrequency(s string) map[rune]int
  // Return a map of each rune to its count in s.

func IsPangram(s string) bool
  // True if s contains every letter a-z (case-insensitive).

func MostFrequentChar(s string) (rune, int)
  // Return the most frequent rune and its count.
  // On ties, return any one of the tied chars.

All 5 tests in strutils_test.go must pass.
